// Estilo PROCEDURAL: datos sueltos y procedimientos que los modifican, paso a paso
const CAPACIDAD_KG = 120;
const paquetes = [];     // lo que va en la camioneta: { id, kg }
const rechazos = [];     // ids que no entraron

function kgCargados() {
  let total = 0;
  for (let i = 0; i < paquetes.length; i++) total += paquetes[i].kg;
  return total;
}

function cargar(id, kg) {
  if (kgCargados() + kg > CAPACIDAD_KG) {
    rechazos.push(id);
    return false;
  }
  paquetes.push({ id, kg });
  return true;
}

function entregar(id) {
  for (let i = 0; i < paquetes.length; i++) {
    if (paquetes[i].id === id) {
      paquetes.splice(i, 1);
      return true;
    }
  }
  return false;
}

function resumen() {
  const ids = [];
  for (let i = 0; i < paquetes.length; i++) ids.push(paquetes[i].id);
  return { pendientes: ids, kg: kgCargados(), rechazos: rechazos.slice() };
}

