// Estilo ORIENTADO A OBJETOS: el estado y las operaciones viven juntos dentro de un objeto
class Camioneta {
  #capacidad;
  #paquetes = [];
  #rechazos = [];

  constructor(capacidadKg) {
    this.#capacidad = capacidadKg;
  }

  get kgCargados() {
    return this.#paquetes.reduce((total, p) => total + p.kg, 0);
  }

  cargar(id, kg) {
    if (this.kgCargados + kg > this.#capacidad) {
      this.#rechazos.push(id);
      return false;
    }
    this.#paquetes.push({ id, kg });
    return true;
  }

  entregar(id) {
    const antes = this.#paquetes.length;
    this.#paquetes = this.#paquetes.filter((p) => p.id !== id);
    return this.#paquetes.length < antes;
  }

  resumen() {
    return { pendientes: this.#paquetes.map((p) => p.id), kg: this.kgCargados, rechazos: [...this.#rechazos] };
  }
}

