#include <stdio.h>
#include <string.h>

#define MAX_PAQ 16

typedef struct { char id[8]; int kg; } Paquete;
typedef struct { int capacidad; int n; Paquete paq[MAX_PAQ]; int rechazos; } Camioneta;

int kg_cargados(const Camioneta *c) {
    int total = 0;
    for (int i = 0; i < c->n; i++) total += c->paq[i].kg;
    return total;
}

int cargar(Camioneta *c, const char *id, int kg) {
    if (kg_cargados(c) + kg > c->capacidad || c->n == MAX_PAQ) { c->rechazos++; return 0; }
    strcpy(c->paq[c->n].id, id);
    c->paq[c->n].kg = kg;
    c->n++;
    return 1;
}

int entregar(Camioneta *c, const char *id) {
    for (int i = 0; i < c->n; i++) {
        if (strcmp(c->paq[i].id, id) == 0) {
            for (int j = i; j < c->n - 1; j++) c->paq[j] = c->paq[j + 1];
            c->n--;
            return 1;
        }
    }
    return 0;
}

int main(void) {
    Camioneta c = { .capacidad = 120 };      /* todo lo demás en cero */
    cargar(&c, "P1", 50);
    cargar(&c, "P2", 40);
    cargar(&c, "P3", 45);                    /* rechazado */
    entregar(&c, "P1");
    cargar(&c, "P3", 45);
    printf("pendientes:");
    for (int i = 0; i < c.n; i++) printf(" %s", c.paq[i].id);
    printf(" | kg: %d | rechazos: %d\n", kg_cargados(&c), c.rechazos);
    return 0;
}

from dataclasses import dataclass, replace, FrozenInstanceError

@dataclass(frozen=True)
class Estado:
    capacidad: int
    paquetes: tuple = ()
    rechazos: tuple = ()

def kg_cargados(e):
    return sum(kg for _, kg in e.paquetes)

def cargar(e, id, kg):
    if kg_cargados(e) + kg > e.capacidad:
        return replace(e, rechazos=e.rechazos + (id,))
    return replace(e, paquetes=e.paquetes + ((id, kg),))

def entregar(e, id):
    return replace(e, paquetes=tuple(p for p in e.paquetes if p[0] != id))

