struct Paquete { id: &'static str, kg: u32 }

fn kg_pendientes(paquetes: &[Paquete]) -> u32 {
    paquetes.iter().map(|p| p.kg).sum()
}

fn main() {
    let paquetes = vec![Paquete { id: "P2", kg: 40 }, Paquete { id: "P3", kg: 45 }];
    let pesados: Vec<&str> = paquetes.iter().filter(|p| p.kg > 42).map(|p| p.id).collect();
    println!("{} kg, pesados: {:?}", kg_pendientes(&paquetes), pesados);
}
